struct PlaceOrderService {
    let orders: OrderRepository
    let customers: CustomerRepository

    func place(_ cmd: PlaceOrderCommand, on db: Database) async throws -> OrderID {
        try await db.transaction { tx in           // commits on return, rolls back on throw
            let customer = try await customers.ofID(cmd.customerID, on: tx)
            let order = try customer.placeOrder(cmd.items)   // the aggregate decides
            try await orders.add(order, on: tx)
            return order.id
        }
    }
}
